// 動物耳朵（畫在頭圓之前 → 耳朵在頭後面）
function animalEars(g, c, x, ty, R) {
  switch (c.animal) {
    case 'rabbit':
      g.fillStyle = c.color;
      [-1, 1].forEach(function (s) {
        g.beginPath(); g.ellipse(x + s * R * .38, ty - R * 1.05, R * .18, R * .5, s * .18, 0, 6.283); g.fill();
      });
      g.fillStyle = 'rgba(255,140,170,.8)';
      [-1, 1].forEach(function (s) {
        g.beginPath(); g.ellipse(x + s * R * .38, ty - R * 1.0, R * .09, R * .32, s * .18, 0, 6.283); g.fill();
      });
      break;
    case 'bear':
      g.fillStyle = c.dark;
      [-1, 1].forEach(function (s) {
        g.beginPath(); g.arc(x + s * R * .62, ty - R * .72, R * .26, 0, 6.283); g.fill();
      });
      g.fillStyle = 'rgba(255,225,185,.6)';
      [-1, 1].forEach(function (s) {
        g.beginPath(); g.arc(x + s * R * .62, ty - R * .72, R * .13, 0, 6.283); g.fill();
      });
      break;
    case 'pig':
      g.fillStyle = c.dark;
      [-1, 1].forEach(function (s) {
        g.beginPath(); g.ellipse(x + s * R * .55, ty - R * .78, R * .2, R * .26, s * .5, 0, 6.283); g.fill();
      });
      break;
    case 'frog':
      g.fillStyle = c.color;
      [-1, 1].forEach(function (s) {
        g.beginPath(); g.arc(x + s * R * .45, ty - R * .88, R * .24, 0, 6.283); g.fill();
      });
      break;
    case 'cat':
      g.fillStyle = c.color;
      [-1, 1].forEach(function (s) {
        g.beginPath();
        g.moveTo(x + s * R * .3 - R * .22, ty - R * .72);
        g.lineTo(x + s * R * .55, ty - R * 1.28);
        g.lineTo(x + s * R * .3 + R * .3, ty - R * .62);
        g.closePath(); g.fill();
      });
      g.fillStyle = 'rgba(255,140,170,.75)';
      [-1, 1].forEach(function (s) {
        g.beginPath();
        g.moveTo(x + s * R * .36 - R * .06, ty - R * .84);
        g.lineTo(x + s * R * .48, ty - R * 1.1);
        g.lineTo(x + s * R * .36 + R * .1, ty - R * .78);
        g.closePath(); g.fill();
      });
      break;
    case 'panda':
      g.fillStyle = c.dark;
      [-1, 1].forEach(function (s) {
        g.beginPath(); g.arc(x + s * R * .62, ty - R * .72, R * .26, 0, 6.283); g.fill();
      });
      break;
    case 'dog':
      g.fillStyle = c.dark;
      [-1, 1].forEach(function (s) {
        g.beginPath(); g.ellipse(x + s * R * .88, ty - R * .05, R * .24, R * .46, s * .3, 0, 6.283); g.fill();
      });
      break;
    case 'chick':
      g.strokeStyle = c.dark; g.lineWidth = Math.max(1.5, R * .09); g.lineCap = 'round';
      g.beginPath(); g.moveTo(x, ty - R * .95);
      g.quadraticCurveTo(x + R * .12, ty - R * 1.28, x + R * .32, ty - R * 1.16);
      g.stroke(); g.lineWidth = 1;
      break;
  }
}
// 臉部特徵（畫在眼睛之前：熊貓眼罩、青蛙眼珠）
function animalFaceUnder(g, c, x, ty, R) {
  if (c.animal === 'panda') {
    g.fillStyle = c.dark;
    g.beginPath(); g.ellipse(x - R * .3, ty - R * .02, R * .25, R * .31, -.3, 0, 6.283); g.fill();
    g.beginPath(); g.ellipse(x + R * .3, ty - R * .02, R * .25, R * .31, .3, 0, 6.283); g.fill();
  }
  if (c.animal === 'frog') {
    g.fillStyle = '#fff';
    g.beginPath(); g.arc(x - R * .45, ty - R * .88, R * .15, 0, 6.283); g.fill();
    g.beginPath(); g.arc(x + R * .45, ty - R * .88, R * .15, 0, 6.283); g.fill();
    g.fillStyle = '#1b2430';
    g.beginPath(); g.arc(x - R * .45, ty - R * .88, R * .08, 0, 6.283); g.fill();
    g.beginPath(); g.arc(x + R * .45, ty - R * .88, R * .08, 0, 6.283); g.fill();
  }
}
// 臉部特徵（畫在眼睛之後：豬鼻、雞嘴、貓鬚、狗鼻）
function animalFaceAfter(g, c, x, ty, R) {
  switch (c.animal) {
    case 'pig':
      g.fillStyle = '#ff8fb0';
      g.beginPath(); g.ellipse(x, ty + R * .32, R * .3, R * .2, 0, 0, 6.283); g.fill();
      g.fillStyle = '#c95f80';
      g.beginPath(); g.arc(x - R * .1, ty + R * .32, R * .05, 0, 6.283); g.fill();
      g.beginPath(); g.arc(x + R * .1, ty + R * .32, R * .05, 0, 6.283); g.fill();
      break;
    case 'chick':
      g.fillStyle = '#ff9d3d';
      g.beginPath();
      g.moveTo(x - R * .16, ty + R * .16);
      g.lineTo(x + R * .16, ty + R * .16);
      g.lineTo(x, ty + R * .36);
      g.closePath(); g.fill();
      break;
    case 'cat':
      g.strokeStyle = 'rgba(255,255,255,.85)'; g.lineWidth = 1.2;
      [-1, 1].forEach(function (s) {
        for (let i = -1; i <= 1; i++) {
          g.beginPath();
          g.moveTo(x + s * R * .2, ty + R * .22);
          g.lineTo(x + s * R * .78, ty + R * .22 + i * R * .12);
          g.stroke();
        }
      });
      g.lineWidth = 1;
      g.fillStyle = '#ff8fb0';
      g.beginPath();
      g.moveTo(x - R * .08, ty + R * .16);
      g.lineTo(x + R * .08, ty + R * .16);
      g.lineTo(x, ty + R * .28);
      g.closePath(); g.fill();
      break;
    case 'dog':
      g.fillStyle = '#3a2c1c';
      g.beginPath(); g.ellipse(x, ty + R * .3, R * .15, R * .11, 0, 0, 6.283); g.fill();
      g.strokeStyle = 'rgba(58,44,28,.55)'; g.lineWidth = 1.4;
      g.beginPath(); g.moveTo(x, ty + R * .41); g.lineTo(x, ty + R * .52); g.stroke();
      g.lineWidth = 1;
      break;
  }
}

// ---- 角色配件：對應選角圖的 8 隻（兔花環、熊藍領巾、狗紅外套、貓魚骨T、豬綠領結、熊貓竹子、青蛙荷葉帽、雞蛋殼帽） ----
// 穿在身上的（畫在身體上、手與頭之前）：領巾／外套／T 恤／領結
function animalWear(g, c, x, y, R, bob) {
  const oy = -(bob || 0) * .6;
  switch (c.animal) {
    case 'rabbit':
      // 脖子上的粉紅蝴蝶結
      g.fillStyle = '#ff7fa8';
      g.beginPath(); g.moveTo(x, y + R * .50 + oy); g.lineTo(x - R * .30, y + R * .34 + oy); g.lineTo(x - R * .30, y + R * .66 + oy); g.closePath(); g.fill();
      g.beginPath(); g.moveTo(x, y + R * .50 + oy); g.lineTo(x + R * .30, y + R * .34 + oy); g.lineTo(x + R * .30, y + R * .66 + oy); g.closePath(); g.fill();
      g.fillStyle = '#ffa8c6';
      g.beginPath(); g.arc(x, y + R * .50 + oy, R * .095, 0, 6.283); g.fill();
      break;
    case 'bear':
      // 藍色三角領巾
      g.fillStyle = '#3f7fc4';
      g.beginPath();
      g.moveTo(x - R * .34, y + R * .46 + oy); g.lineTo(x + R * .34, y + R * .46 + oy);
      g.lineTo(x, y + R * .96 + oy); g.closePath(); g.fill();
      g.fillStyle = 'rgba(255,255,255,.30)';
      g.beginPath();
      g.moveTo(x - R * .34, y + R * .46 + oy); g.lineTo(x + R * .34, y + R * .46 + oy);
      g.lineTo(x, y + R * .60 + oy); g.closePath(); g.fill();
      break;
    case 'dog':
      // 紅色連帽外套＋白色拉繩
      g.fillStyle = '#e2503f';
      if (g.roundRect) { g.beginPath(); g.roundRect(x - R * .56, y + R * .24 + oy, R * 1.12, R * .62, R * .28); g.fill(); }
      else { g.beginPath(); g.ellipse(x, y + R * .55 + oy, R * .56, R * .31, 0, 0, 6.283); g.fill(); }
      g.fillStyle = '#b83a2c';
      g.beginPath(); g.ellipse(x, y + R * .30 + oy, R * .30, R * .13, 0, 0, 6.283); g.fill();
      g.strokeStyle = '#fff1e6'; g.lineWidth = Math.max(1, R * .07); g.lineCap = 'round';
      g.beginPath(); g.moveTo(x - R * .12, y + R * .36 + oy); g.lineTo(x - R * .16, y + R * .58 + oy); g.stroke();
      g.beginPath(); g.moveTo(x + R * .12, y + R * .36 + oy); g.lineTo(x + R * .16, y + R * .58 + oy); g.stroke();
      g.lineWidth = 1; g.lineCap = 'butt';
      break;
    case 'cat':
      // 白 T 恤＋魚骨頭圖案
      g.fillStyle = '#f4f6fb';
      if (g.roundRect) { g.beginPath(); g.roundRect(x - R * .46, y + R * .26 + oy, R * .92, R * .58, R * .22); g.fill(); }
      else { g.beginPath(); g.ellipse(x, y + R * .55 + oy, R * .46, R * .29, 0, 0, 6.283); g.fill(); }
      g.strokeStyle = '#8ea2c4'; g.lineWidth = Math.max(1, R * .06); g.lineCap = 'round';
      g.beginPath(); g.moveTo(x - R * .18, y + R * .56 + oy); g.lineTo(x + R * .16, y + R * .56 + oy); g.stroke();
      for (let i = -1; i <= 1; i++) {
        g.beginPath();
        g.moveTo(x + i * R * .12, y + R * .48 + oy); g.lineTo(x + i * R * .12, y + R * .64 + oy);
        g.stroke();
      }
      g.beginPath(); g.moveTo(x + R * .16, y + R * .56 + oy); g.lineTo(x + R * .26, y + R * .44 + oy); g.stroke();
      g.beginPath(); g.moveTo(x + R * .16, y + R * .56 + oy); g.lineTo(x + R * .26, y + R * .68 + oy); g.stroke();
      g.lineWidth = 1; g.lineCap = 'butt';
      break;
    case 'pig':
      // 綠色領結
      g.fillStyle = '#3fb57a';
      g.beginPath(); g.moveTo(x, y + R * .50 + oy); g.lineTo(x - R * .30, y + R * .34 + oy); g.lineTo(x - R * .30, y + R * .66 + oy); g.closePath(); g.fill();
      g.beginPath(); g.moveTo(x, y + R * .50 + oy); g.lineTo(x + R * .30, y + R * .34 + oy); g.lineTo(x + R * .30, y + R * .66 + oy); g.closePath(); g.fill();
      g.fillStyle = '#66d99b';
      g.beginPath(); g.arc(x, y + R * .50 + oy, R * .095, 0, 6.283); g.fill();
      break;
  }
}
// 戴在頭上的／拿在手上的（畫在最上層）：花環／竹子／荷葉帽／蛋殼帽
function animalAccessory(g, c, x, y, topY, R) {
  switch (c.animal) {
    case 'rabbit': {
      // 頭頂花環（三朵小花）
      [[-.34, -.94, '#ffd166'], [-.04, -1.06, '#ff9fc0'], [.30, -.96, '#9be59b']].forEach(function (f) {
        const fx = x + R * f[0], fy = topY + R * f[1];
        g.fillStyle = f[2];
        for (let i = 0; i < 5; i++) {
          const a = i / 5 * 6.283;
          g.beginPath(); g.arc(fx + Math.cos(a) * R * .085, fy + Math.sin(a) * R * .085, R * .072, 0, 6.283); g.fill();
        }
        g.fillStyle = '#fff6cf';
        g.beginPath(); g.arc(fx, fy, R * .055, 0, 6.283); g.fill();
      });
      break;
    }
    case 'panda':
      // 手裡握著的竹子（拿在身體右側，不會擋住臉）
      g.strokeStyle = '#5cb85c'; g.lineWidth = Math.max(1.3, R * .11); g.lineCap = 'round';
      g.beginPath(); g.moveTo(x + R * .84, y + R * .66); g.lineTo(x + R * .78, y - R * .26); g.stroke();
      g.lineWidth = 1; g.lineCap = 'butt';
      g.strokeStyle = '#8ee08e'; g.lineWidth = Math.max(1, R * .05);
      g.beginPath(); g.moveTo(x + R * .84, y + R * .3); g.lineTo(x + R * .9, y + R * .34); g.stroke();
      g.lineWidth = 1;
      g.fillStyle = '#7fd47f';
      [-.34, -.18].forEach(function (dy, i) {
        g.beginPath(); g.ellipse(x + R * (.92 + i * .02), y + R * dy, R * .15, R * .07, -.5 + i * .5, 0, 6.283); g.fill();
      });
      break;
    case 'frog': {
      // 荷葉帽：斜戴在頭上（一片荷葉，右側開缺口）
      g.save();
      if (g.translate) {
        g.translate(x - R * .10, topY - R * .95);
        g.rotate(-.26);
        g.fillStyle = '#3f9e57';
        g.beginPath(); g.ellipse(0, 0, R * .80, R * .27, 0, 0, 6.283); g.fill();
        g.fillStyle = '#5cc075';
        g.beginPath(); g.ellipse(-R * .10, -R * .05, R * .54, R * .15, 0, 0, 6.283); g.fill();
        // 缺口（切一小塊背景色調的陰影，讓它看起來像荷葉）
        g.fillStyle = 'rgba(0,0,0,.20)';
        g.beginPath();
        g.moveTo(R * .24, -R * .22);
        g.lineTo(R * .80, R * .04);
        g.lineTo(R * .26, R * .14);
        g.closePath(); g.fill();
        g.restore();
      } else {
        g.fillStyle = '#3f9e57';
        g.beginPath(); g.ellipse(x, topY - R * .95, R * .80, R * .27, 0, 0, 6.283); g.fill();
      }
      break;
    }
    case 'chick': {
      // 蛋殼帽（半圓殼 + 明顯鋸齒下緣）
      const yb = topY - R * .34;
      g.fillStyle = '#fdfdf6';
      g.beginPath();
      g.arc(x, yb, R * .72, Math.PI, 0);
      const n = 5;
      for (let i = 0; i <= n; i++) {
        const px = x + R * .72 - (i * R * 1.44 / n);
        const py = yb + (i % 2 ? R * .28 : 0);
        g.lineTo(px, py);
      }
      g.closePath(); g.fill();
      // 殼上一點高光
      g.fillStyle = 'rgba(255,255,255,.85)';
      g.beginPath(); g.ellipse(x - R * .24, yb - R * .40, R * .18, R * .09, -.55, 0, 6.283); g.fill();
      g.fillStyle = 'rgba(160,180,205,.35)';
      g.beginPath(); g.ellipse(x + R * .2, yb - R * .30, R * .12, R * .06, -.4, 0, 6.283); g.fill();
      break;
    }
  }
}

// 胖胖動物頭像（大圓頭 + 動物耳朵 + 大眼睛），畫在任意 canvas 上
function drawAvatarOn(cnv, chIdx) {
  const c = CHARACTERS[((chIdx % CHARACTERS.length) + CHARACTERS.length) % CHARACTERS.length];
  const g = cnv.getContext && cnv.getContext('2d');
  if (!g) return;
  const S = cnv.width;
  g.clearRect(0, 0, S, S);
  const im = Sprites.get(c.animal);
  if (im && g.drawImage) {
    // 頭像縮小一點（原本幾乎撐滿整個圓框，看起來太擠）
    const h = S * .84, sc = h / im.naturalHeight, w = im.naturalWidth * sc;
    g.drawImage(im, (S - w) / 2, S * .94 - h, w, h);
    return;
  }
  const cx = S / 2, cy = S * .58, R = S * .30;
  animalEars(g, c, cx, cy, R);
  // 頭
  g.fillStyle = c.color;
  g.beginPath(); g.arc(cx, cy, R, 0, 6.283); g.fill();
  g.fillStyle = 'rgba(255,255,255,.30)';
  g.beginPath(); g.ellipse(cx - R * .35, cy - R * .4, R * .38, R * .2, -.5, 0, 6.283); g.fill();
  animalFaceUnder(g, c, cx, cy, R);
  // 大眼睛
  g.fillStyle = '#1b2430';
  g.beginPath(); g.ellipse(cx - R * .3, cy - R * .05, R * .13, R * .2, 0, 0, 6.283); g.fill();
  g.beginPath(); g.ellipse(cx + R * .3, cy - R * .05, R * .13, R * .2, 0, 0, 6.283); g.fill();
  g.fillStyle = '#fff';
  g.beginPath(); g.arc(cx - R * .26, cy - R * .12, R * .05, 0, 6.283); g.fill();
  g.beginPath(); g.arc(cx + R * .34, cy - R * .12, R * .05, 0, 6.283); g.fill();
  // 腮紅
  g.fillStyle = 'rgba(255,140,170,.55)';
  g.beginPath(); g.ellipse(cx - R * .52, cy + R * .18, R * .13, R * .08, 0, 0, 6.283); g.fill();
  g.beginPath(); g.ellipse(cx + R * .52, cy + R * .18, R * .13, R * .08, 0, 0, 6.283); g.fill();
  animalFaceAfter(g, c, cx, cy, R);
}
function drawAvatarsIn(wrap) {
  wrap.querySelectorAll('canvas.pav').forEach(function (cnv) {
    drawAvatarOn(cnv, parseInt(cnv.getAttribute('data-ch'), 10) || 0);
  });
}

