// ---------- 選角預覽：8 隻角色在卡片裡來回走動（與遊戲內用同一套 drawCharBody 畫法） ----------
const CharPreview = (function () {
    try {
      return (function () {
  let items = [], t = 0, hops = {};
  function mount(root) {
    items = [];
    if (!root || !root.querySelectorAll) return;
    root.querySelectorAll('canvas.chpv').forEach(function (cnv) {
      const g = cnv.getContext && cnv.getContext('2d');
      if (!g) return;
      items.push({ cnv: cnv, g: g, ch: parseInt(cnv.getAttribute('data-ch'), 10) || 0 });
    });
  }
  function hop(i) { hops[i] = 1; }        // 被選中 → 輕輕彈一下
  function drawOne(o, now) {
    const W = o.cnv.width, H = o.cnv.height, g = o.g;
    const c = CHARACTERS[o.ch % CHARACTERS.length];
    g.clearRect(0, 0, W, H);
    // 來回踱步：慢速左右走 + 轉身（走路動作放慢，手腳才看得出來在動）
    const phase = now * .55 + o.ch * .7;
    const cx = W / 2 + Math.sin(phase) * W * .062;
    const facing = Math.cos(phase) >= 0 ? 'right' : 'left';
    const walk = now * 4.6;
    // 選到時：小小蹲一下再站起來（不是大跳）
    const hp = hops[o.ch] || 0;
    const jump = hp > 0 ? Math.sin((1 - hp) * Math.PI) * H * .075 : 0;
    const hasImg = !!Sprites.get(c.animal);
    const R = hasImg ? (H * .70) / 3.75 : W * .27;
    const footY = hasImg ? H * .955 - jump : H * .70 - jump;
    // 地面影子（跳起來會縮小變淡）
    g.fillStyle = 'rgba(0,0,0,' + Math.max(.08, .30 - jump / H * .8).toFixed(3) + ')';
    g.beginPath(); g.ellipse(cx, footY + H * .015, Math.max(6, R * .92 - jump * .3), Math.max(3, R * .22 - jump * .08), 0, 0, 6.283); g.fill();
    if (hasImg) {
      drawSpriteChar(g, c, cx, footY - R * .82, R, { walk: walk, moving: true, facing: facing, amp: 1.15, idle: now });
    } else {
      drawCharBody(g, c, cx, H * .70 + H * .0, R, {
        walk: walk, moving: true, facing: facing, bob: Math.abs(Math.sin(walk)) * W * .018,
        blink: ((now + o.ch * .41) % 3.4) < .12, amp: R / 14
      });
    }
  }
  function tick(dt) {
    if (!items.length) return;
    // 只有停在「選角」畫面上才跑動畫（v4.0：RPG 創角畫面也有選角）
    if (Screen.current !== 'solo' && Screen.current !== 'rpg') return;
    t += dt;
    for (let i = 0; i < items.length; i++) {
      const k = items[i].ch;
      if (hops[k] > 0) hops[k] = Math.max(0, hops[k] - dt * 1.15);
      drawOne(items[i], t);
    }
  }
  return { mount: mount, tick: tick, hop: hop, items: function () { return items; } };
      })();
    } catch (__e) {
      __bootFail('CharPreview', __e);
      return (typeof __stubModule === 'function') ? __stubModule('CharPreview') : {};
    }
  })();

// 單人難易度設定（敵人數量／速度／魔王血量／恐龍蛋數量）
// v2.4：三種難度的 BOSS 統一 5 下（血條滿格 = 5，打五下就贏）
const BOSS_HITS = 5;
const SOLO_DIFF = {
  easy:   { enemy: .62, speed: .80, bossHp: BOSS_HITS, eggs: 3, label: '😇 簡單' },
  normal: { enemy: 1,   speed: 1,   bossHp: BOSS_HITS, eggs: 2, label: '🙂 普通' },
  hard:   { enemy: 1.45, speed: 1.22, bossHp: BOSS_HITS, eggs: 1, label: '😈 困難' }
};
function soloDiffCfg() { return SOLO_DIFF[settings.soloDiff] || SOLO_DIFF.normal; }
// 單人關卡時間（0 = 無限）
function soloTimeVal() {
  const t = parseInt(settings.soloTime, 10);
  return t > 0 ? t : 0;
}

function startSolo(stage, bossRush) {
  // v4.3：行為足跡（後台客服核對「卡在哪一關」用）
  try { if (typeof Cloud !== 'undefined' && Cloud.track) Cloud.track(bossRush ? 'boss' : 'play', stage); } catch (e) {}
  Game.mode = 'solo';
  // v4.17：修舊 bug —— 玩過 RPG 之後 Game.rpg 一直是 true，
  //   回到單人闖關會走 RPG 的扣血邏輯（hpCur 是 undefined → 永遠不會死）。
  Game.rpg = false;
  Game.pets = [];
  Game.bossRush = !!bossRush;
  // v4.14：單人闖關變成 32 張地圖 → 先把關號夾在合法範圍，主題改成看 MAP32
  stage = Math.max(1, Math.min(SOLO_STAGES, stage || 1));
  Game.stage = stage;
  Game.theme = THEMES[soloInfo(stage).theme] || THEMES[0];
  Game.mapInfo = soloInfo(stage);
  Game.players = [];
  Game.endShown = false;        // 重新開始 → 結束畫面標記歸零
  Game.state = 'idle';          // 清掉上一場的 'over' / 'roundover'，避免卡住不更新
  paused = false;
  const soloScheme = settings.ctrl === 'auto' ? Input.schemes.auto
    : ctrlMode() === 'touch' ? Input.schemes.touch
    : ctrlMode() === 'pad' ? Input.schemes.pad(0) : Input.schemes.kb1;
  const p = makePlayer(0, settings.soloChar || 0, soloScheme, { px: 0, py: 0 });
  p.lives = Game.bossRush ? 3 : 3;
  p.score = 0;
  Game.players.push(p);
  p.name = settings.playerName || '';   // v4.8：固定暱稱
  Screen.show('game');
  resizeView();                 // 先量測實際畫面尺寸，地圖格子大小才正確
  buildSoloStage(stage, true);
  const tSec = soloTimeVal();
  showOverlay({
    title: Game.bossRush ? t('solo.ovBossTitle', { name: soloInfo(stage).n }) : t('solo.ovTitle', { n: stage, name: soloInfo(stage).n }),
    sub: (Game.bossRush ? t('solo.ovBossSub') : (soloIsBoss(stage) ? t('solo.ovBossSub2') : t('solo.ovSub'))) +
      t('solo.ovTime', { d: soloDiffCfg().label, t: (tSec ? fmtTime(tSec) : t('time.inf')) }),
    btn: t('solo.ovGo'),
    action: function () { beginCountdown('battle'); }
  });
  AudioSys.startBGM(stageBGM(stage));
  updateHud();
  enterImmersive();          // 手機：全螢幕＋鎖定橫向
}
// 首頁「挑戰 BOSS」：直接打最終魔王（第 32 張地圖「魔王之間」），場上沒有小怪
function startBossRush() { startSolo(SOLO_STAGES, true); }

function buildSoloStage(stage, fresh) {
  const size = SIZES[settings.size] || SIZES.M;
  const cols = size[0], rows = size[1];
  const diff = soloDiffCfg();
  const p = Game.players[0];
  const info = soloInfo(stage);
  const theme = THEMES[info.theme] || THEMES[0];
  Game.theme = theme;
  Game.mapInfo = info;
  // v4.14：單人闖關跟 RPG 一樣走「有機地形」（洞穴／迷宮／環形／樑柱…）。
  //   固定種子 → 同一張地圖每次進去長得都一樣，玩家可以記圖、練路線。
  const seed = 3000 + info.idx * 6151 + cols * 31 + rows * 13;
  // v4.14：道具量也改成連續曲線（32 關不能沿用「13 + 關號×1.5」，後段會多到每塊磚都有）
  buildOrganicMap(cols, rows, theme, info, rngFrom(seed), {
    seed: seed, items: Math.min(18, 14 + Math.round(stage * .15))
  });
  p.x = 1 * Game.T + Game.T / 2;
  p.y = 1 * Game.T + Game.T / 2;
  p.alive = true; p.invuln = 2; p.carry = null; p.slide = null; p.warpLock = '';
  if (fresh) resetPlayerStats(p);
  // 敵人（多樣化：亂走／快速亂走／追人／飛行穿牆＋技能怪）
  Game.enemies = [];
  if (!Game.bossRush) {
    // v4.14：前 7 關沿用 v2.8 的怪物量曲線（手感不變），第 8 關之後接上連續成長；
    //   v4.16：只有第 32 關是最終魔王關，小怪只留 45%，讓玩家專心打王
    // v4.17：小怪量再往上加（前 7 關 +約 35%，之後接連續成長，上限 26）
    const SOLO_WAVE = [8, 11, 12, 15, 16, 19, 20];
    const base0 = stage <= 7 ? SOLO_WAVE[stage - 1] : Math.min(26, 17 + Math.round((stage - 7) * .55));
    const base = soloIsBoss(stage) ? Math.round(base0 * .5) : base0;
    const n = Math.max(0, Math.round(base * diff.enemy * (cols * rows) / (15 * 13)));
    // v4.27：小怪名單全部來自「八大關卡生態表」—— 同一個大關的 4 張地圖只會出現那 6 隻，
    //   玩家看主題就知道會遇到什麼，難度也隨大關一階一階上去。
    const types = stageTypes(stage);
    Game.roster = stageRoster(stage).slice();
    const pool = types.slice();     // 先輪流出一輪，保證每種都登場
    // 怪的成長等級封頂在 8（原本只有 8 關，現在 32 關不能讓速度一路漲到追不到）
    const lv = Math.min(8, Math.ceil(stage / 4));
    for (let i = 0; i < n; i++) {
      let x, y, tries = 0;
      do {
        x = 1 + rand(cols - 2); y = 1 + rand(rows - 2);
        tries++;
      } while ((cellAt(x, y) !== 0 || (x < 4 && y < 4) || bombAt(x, y)) && tries < 200);
      Game.enemies.push(makeEnemy(x, y, pool.length ? pool.shift() : pick(types), lv, diff.speed));
    }
  }
  // v4.16：只有第 32 關「魔王之間」會出 BOSS（其餘 31 關都不再放魔王）
  if (Game.bossRush || soloIsBoss(stage)) {
    // v1.8：BOSS 從「畫面下方」登場（舊版在最上排出來，一開局就壓在玩家頭上）
    const by = Math.max(1, rows - 2);
    let bx = clamp(Math.floor(cols / 2), 1, cols - 2);
    // 別剛好坐在傳送門上；下方空間不足就往左／右退一格
    if (Game.door && Game.door.x === bx && Game.door.y === by) bx = (bx > 1 ? bx - 1 : bx + 1);
    Game.grid[by][bx] = 0;                       // 登場那一格先清空，保證站得住
    // 魔王血量：最終魔王固定 12 下（首頁「挑戰 BOSS」連戰仍是各難度的 5 下）
    const bossHp = Game.bossRush ? diff.bossHp : 12;
    const boss = makeBoss(bx, by, bossHp);
    boss.dirName = 'up';                         // 從下方上來 → 面朝上方
    Game.enemies.push(boss);
  }
  // 恐龍蛋：炸得到，走上蛋格就會孵出恐龍
  spawnEggs(Game.bossRush ? 2 : diff.eggs);
  const tSec = soloTimeVal();
  Game.timer = tSec > 0 ? tSec : Infinity;
  Game.bombs = []; Game.flames = []; Game.items = []; Game.particles = [];
  Game.pops = []; Game.edgeFx = 0;          // v4.5：換場清掉上次殘留的受傷反饋
  Game.sdIndex = 0; Game.sdList = [];
  hideOverlay();
  buildSdList();
  spawnPets();                       // v4.17：把商店雇用的隨從帶進關卡
}

