  const st = artStyle();
  const set = artSet(st);
  if (artBlit(big ? set.softBig : set.soft, (px * 13 + py * 7) | 0, px, py, T)) return;
  ctx.fillStyle = base || '#c0844c'; ctx.fillRect(px, py, T, T);
