// 手把加入偵測（對戰設定畫面）
setInterval(function () {
  if (Screen.current !== 'battle') return;
  const edges = Input.pollPads();
  let changed = false;
  edges.forEach(function (e, i) {
    if (!e) return;
    const slot = Battle.slots[i + 2];
    if (slot && !slot.joined) {
      slot.joined = true;
      slot.forceAi = false;   // 手把接手，取消 AI 託管
      AudioSys.sfx('item');
      changed = true;
    }
  });
  if (changed) Battle.renderSlots();
}, 100);

